function borrow(uint amount) external {
  debt[msg.sender] += amount;
  uint hf = (collateral[msg.sender] * LIQ_THRESHOLD) / debt[msg.sender];
  require(hf >= 1e18, "would be undercollateralized");
  token.transfer(msg.sender, amount);
}

function liquidate(address user, uint repayAmount) external {
  require(healthFactor(user) < 1e18, "not liquidatable");
  uint seized = repayAmount * 105 / 100; // 5% bonus
  collateral[user] -= seized;
  debt[user] -= repayAmount;
}
